import pandas as pd

def clean(df):
    df = df.copy()
    # Remove exact duplicate rows
    df = df.drop_duplicates(keep='first')
    # Standardize text labels by stripping whitespace
    for col in ['Category', 'Region']:
        if col in df.columns:
            df[col] = df[col].str.strip()
    # Convert Price to numeric, removing currency symbols
    if 'Price' in df.columns:
        df['Price'] = pd.to_numeric(
            df['Price'].astype(str).str.replace(r'[$,]', '', regex=True),
            errors='coerce'
        )
    # Recompute Revenue so it matches Quantity * Price
    if {'Quantity', 'Price'}.issubset(df.columns):
        df['Revenue'] = df['Quantity'] * df['Price']
    # Drop rows missing the grouping key
    df = df.dropna(subset=['Region'])
    return df

def answer(df):
    result = df.groupby('Region')['Quantity'].sum().astype(int)
    return result.to_dict()
